import json
import sys

EVENT_STAGE = {
    "page_view": "view",
    "add_to_cart": "cart",
    "purchase": "purchase",
}
STAGES = ("view", "cart", "purchase")


def funnel_counts(events):
    visitor_stages = {}
    for event in events:
        visitor = event.get("visitor_id")
        stage = EVENT_STAGE.get(event.get("event"))
        if visitor is not None and stage is not None:
            visitor_stages.setdefault(visitor, set()).add(stage)

    eligible = set(visitor_stages)
    counts = {}
    for stage in STAGES:
        eligible = {visitor for visitor in eligible if stage in visitor_stages[visitor]}
        counts[stage] = len(eligible)
    return counts


if __name__ == "__main__":
    print(json.dumps(funnel_counts(json.load(sys.stdin)), sort_keys=True))

