module.exports = function debounce(fn, delay) {
  let timer;
  let savedArgs;

  return function (...args) {
    if (!timer) savedArgs = args;
    clearTimeout(timer);
    timer = setTimeout(() => fn(...savedArgs), delay);
  };
};

module.exports = function debounce(fn, delay) {
  let timer;
  let savedArgs;
  let savedContext;

  return function (...args) {
    savedArgs = args;
    savedContext = this;
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(savedContext, savedArgs), delay);
  };
};

