static void reverse_range(char *left, char *right)
{
    while (left < right) {
        char value = *left;
        *left = *right;
        *right = value;
        ++left;
        --right;
    }
}

char *reverse_words(char *text)
{
    char *end = text;
    while (*end != '\0') {
        ++end;
    }
    if (end == text) {
        return text;
    }

    reverse_range(text, end - 1);
    char *word = text;
    for (char *cursor = text; ; ++cursor) {
        if (*cursor == ' ' || *cursor == '\0') {
            if (cursor > word) {
                reverse_range(word, cursor - 1);
            }
            if (*cursor == '\0') {
                break;
            }
            word = cursor + 1;
        }
    }
    return text;
}

int main(void)
{
    char sample[] = "cider tea";
    printf("%s\n", reverse_words(sample));
    return 0;
}

