from fractions import Fraction
import sys


def scale_line(line, factor):
    amount, separator, description = line.rstrip("\n").partition(" ")
    if not separator:
        raise ValueError(f"ingredient line needs a quantity and description: {line!r}")
    scaled = Fraction(amount) * factor
    quantity = str(scaled.numerator) if scaled.denominator == 1 else f"{scaled.numerator}/{scaled.denominator}"
    return f"{quantity} {description}"


def main():
    factor = Fraction(sys.argv[1])
    for line in sys.stdin:
        if line.strip():
            print(scale_line(line, factor))


if __name__ == "__main__":
    main()

