// ProbeTCP reports whether address accepts a TCP connection before timeout.
func ProbeTCP(address string, timeout time.Duration) bool {
	connection, err := net.DialTimeout("tcp", address, timeout)
	if err != nil {
		return false
	}
	_ = connection.Close()
	return true
}

